// Feed-quality readings: the rules for merging a new reading into api/quality-cache.ts,
// shared by the ffprobe run (scripts/probe-quality.ts) and the Fire TV app, which reports
// what it measures on the streams it plays (/api/app/quality).
import { rename } from 'node:fs/promises'
import { QUALITY } from './quality-cache.js'

export type Meta = { w: number; h: number; fps: number; codec: string; name: string; atmos?: true; at?: string; tried?: string }

// The cache is a TS module (not JSON), written as `export const`.
export const QUALITY_HEAD =
  '// Auto-generated by scripts/probe-quality.ts — real probed video metadata (resolution/fps, Atmos audio).\nexport const QUALITY: Record<string, { w: number; h: number; fps: number; codec: string; name: string; atmos?: true; at?: string; tried?: string } | null> = '

/** A reading older than this is replaced by the next one, whatever it shows. */
export const STALE_DAYS = 14
export const staleBefore = (today: string) => new Date(Date.parse(today) - STALE_DAYS * 864e5).toISOString().slice(0, 10)

/** Strictly better reading: height, then fps, then Atmos. */
export const better = (a: Meta | null, b: Meta | null | undefined): boolean =>
  !!a && (!b ? true : a.h !== b.h ? a.h > b.h : a.fps !== b.fps ? a.fps > b.fps : !!a.atmos && !b.atmos)

/**
 * The app's reading merged into a cache entry, or null to keep the entry. Like the probe:
 * fill a missing or dead entry, replace a stale one, upgrade a fresh one. Unlike it, the
 * app's fps is measured from rendered frames, where a 1080i25 feed can read 50, so it
 * never raises the fps of a same-height reading (that would rank interlaced feeds as 50p).
 */
export function mergeAppReading(old: Meta | null | undefined, reading: Meta, today: string): Meta | null {
  const next = { ...reading, at: today }
  if (!old || !(old.at && old.at >= staleBefore(today))) return next
  if (reading.h > old.h || (reading.h === old.h && reading.atmos && !old.atmos)) return { ...next, fps: reading.h === old.h ? old.fps : reading.fps }
  return null
}

let writing = Promise.resolve()
/** Writes the in-memory cache to disk atomically (temp + rename), one write at a time. */
export function saveQuality(file = process.env.QUALITY_CACHE_FILE ?? `${import.meta.dir}/quality-cache.ts`): Promise<void> {
  writing = writing.then(async () => {
    await Bun.write(file + '.tmp', QUALITY_HEAD + JSON.stringify(QUALITY) + '\n')
    await rename(file + '.tmp', file)
  })
  return writing
}
